const resp=$input.first().json;const draft=$('Guion y resumen').first().json;
const raw=resp?.choices?.[0]?.message?.content;
if(!raw||!raw.trim())throw new Error('Auditoría editorial sin respuesta: publicación detenida.');
let parsed;try{parsed=JSON.parse(raw)}catch{throw new Error('La auditoría editorial no devolvió JSON válido.');}
const finalText=String(parsed.corrected_script||'').trim();
if(finalText.length<1600)throw new Error('Guion auditado demasiado corto: publicación detenida.');
const usages={...draft.usage,audit:resp.usage||{}};
const list=[usages.selection||{},usages.analysis||{},usages.script||{},usages.audit||{}];
const sum=k=>list.reduce((acc,u)=>acc+Number(u[k]||0),0);
usages.inputTokens=sum('prompt_tokens');usages.outputTokens=sum('completion_tokens');usages.totalTokens=sum('total_tokens');
const rates=draft.config.costRatesPeak;const priced=[
 {u:usages.selection||{},i:rates.flashIn,o:rates.flashOut},
 {u:usages.analysis||{},i:rates.proIn,o:rates.proOut},
 {u:usages.script||{},i:rates.flashIn,o:rates.flashOut},
 {u:usages.audit||{},i:rates.flashIn,o:rates.flashOut},
];
const estimate=priced.reduce((acc,p)=>acc+(Number(p.u.prompt_tokens||0)*p.i+Number(p.u.completion_tokens||0)*p.o)/1e6,0);
return [{json:{...draft,script:finalText,words:finalText.split(/\s+/).length,usage:usages,costEstimateUSD:Math.round(estimate*1e6)/1e6,auditIssues:(parsed.issues||[]).slice(0,25),auditApproved:parsed.approved===true}}];
